//! Prospective context-compilation contract model (`AFA-devx-P03-F07`).
//! It validates typed context attestations and emits a deterministic admission artifact; it does
//! not retrieve evidence, invoke tools, or make a scientific or clinical conclusion.
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-devx-P03-F07";
pub const CONTRACT_VERSION: &str = "devx-prospective-high-throughput-context-compilation-contract-model/1.0";
pub const INPUT_SCHEMA: &str = "ContextCompilationContractRequest3@1";
pub const OUTPUT_SCHEMA: &str = "CompiledResearchContext6@1";
pub const CONTENT_TYPE: &str = "application/vnd.aurora.devx-compiled-research-context-6+json";
pub const BOUNDARY: &str = "preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ContextEvidenceState { Supported, Unknown, Contradicted, Unmeasured }

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ContextFact4 { pub fact_id: String, pub study_id: String, pub context_type: String, pub scope: String, pub semantic_digest: ContentHash, pub evidence_digest: ContentHash, pub provenance_digest: ContentHash, pub replay_identity: ContentHash, pub evidence_state: ContextEvidenceState, pub policy_allowed: bool, pub protected_closure: bool, pub local_only: bool, pub omission_order: Vec<String>, pub negative_result: bool }

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ContextCompilationContractRequest3 { pub schema_version: String, pub request_id: String, pub workflow_id: String, pub scope: String, pub required_fact_order: Vec<String>, pub required_context_type_order: Vec<String>, pub facts: Vec<ContextFact4>, pub replay_identity: ContentHash, pub policy_allow: bool, pub protected_closure: bool, pub signed_approval: bool, pub agent_authorized: bool, pub raw_data_local: bool, pub aggregate_only: bool, pub adversarial_events: Vec<String>, pub boundary: String }

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ContextContractDisposition { Qualified, Unresolved, Blocked }

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CompiledResearchContext6 { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub request_id: String, pub workflow_id: String, pub scope: String, pub disposition: ContextContractDisposition, pub fact_order: Vec<String>, pub selected_fact_order: Vec<String>, pub unresolved_fact_order: Vec<String>, pub blocked_fact_order: Vec<String>, pub missing_fact_order: Vec<String>, pub context_type_order: Vec<String>, pub selected_context_type_order: Vec<String>, pub missing_context_type_order: Vec<String>, pub semantic_order: Vec<ContentHash>, pub evidence_order: Vec<ContentHash>, pub provenance_order: Vec<ContentHash>, pub omission_order: Vec<String>, pub uncertainty_order: Vec<String>, pub negative_evidence_order: Vec<String>, pub replay_identity: ContentHash, pub context_digest: ContentHash, pub artifact: ContractArtifact, pub effect_receipts: Vec<String>, pub raw_data_local: bool, pub aggregate_only: bool, pub boundary: String }

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ContractArtifact { pub schema_version: String, pub artifact_id: String, pub content_type: String, pub content_hash: ContentHash, pub boundary: String }

#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum ContextContractError { #[error("invalid context contract: {0}")] Invalid(String), #[error("context artifact failed: {0}")] Artifact(String) }
fn invalid(s: impl Into<String>) -> ContextContractError { ContextContractError::Invalid(s.into()) }
fn canonical(v: &[String]) -> bool { v.windows(2).all(|p| p[0] < p[1]) }
fn digest(v: &ContentHash) -> bool { v.as_str().len() == 64 && v.as_str().bytes().all(|b| b.is_ascii_hexdigit()) }

impl CompiledResearchContext6 {
    pub fn validate(&self) -> Result<(), ContextContractError> {
        if self.schema_version != "aurora-research-contract-v1" || self.contract_version != CONTRACT_VERSION || self.feature_id != FEATURE_ID || self.boundary != BOUNDARY || self.artifact.boundary != BOUNDARY || self.artifact.content_type != CONTENT_TYPE || !self.raw_data_local || !self.aggregate_only || self.request_id.trim().is_empty() || self.workflow_id.trim().is_empty() || self.scope.trim().is_empty() || self.fact_order.is_empty() || self.context_type_order.is_empty() || self.semantic_order.is_empty() || self.evidence_order.is_empty() || self.provenance_order.is_empty() || self.effect_receipts.is_empty() { return Err(invalid("context identity, closure, locality, digests, or effects are incomplete")); }
        for values in [&self.fact_order, &self.selected_fact_order, &self.unresolved_fact_order, &self.blocked_fact_order, &self.missing_fact_order, &self.context_type_order, &self.selected_context_type_order, &self.missing_context_type_order, &self.omission_order, &self.uncertainty_order, &self.negative_evidence_order, &self.effect_receipts] { if !canonical(values) { return Err(invalid("context contract ordering is not canonical")); } }
        let all = self.fact_order.iter().cloned().collect::<BTreeSet<_>>(); let parts = self.selected_fact_order.iter().chain(self.unresolved_fact_order.iter()).chain(self.blocked_fact_order.iter()).chain(self.missing_fact_order.iter()).cloned().collect::<BTreeSet<_>>(); if all.len() != self.fact_order.len() || parts != all { return Err(invalid("fact states do not form a complete partition")); }
        if self.selected_context_type_order.iter().chain(self.missing_context_type_order.iter()).any(|id| !self.context_type_order.contains(id)) { return Err(invalid("context type closure is invalid")); }
        if !digest(&self.replay_identity) || !digest(&self.context_digest) || self.artifact.content_hash != self.context_digest { return Err(invalid("context digest is invalid")); }
        if self.disposition == ContextContractDisposition::Qualified && self.effect_receipts != [format!("view:compiled-context:{}", self.request_id)] { return Err(invalid("qualified context effect is invalid")); }
        if self.disposition != ContextContractDisposition::Qualified && self.effect_receipts != ["block:unsafe-release"] { return Err(invalid("non-qualified context must block")); }
        Ok(())
    }
    pub fn digest(&self) -> Result<ContentHash, ContextContractError> { self.validate()?; ContentHash::of_value(&serde_json::to_value(self).map_err(|e| ContextContractError::Artifact(e.to_string()))?).map_err(|e| ContextContractError::Artifact(e.to_string())) }
}

pub fn compile_context_contract(q: &ContextCompilationContractRequest3) -> Result<CompiledResearchContext6, ContextContractError> {
    validate_request(q)?; let mut rows = q.facts.clone(); rows.sort_by(|a,b| a.study_id.cmp(&b.study_id).then(a.fact_id.cmp(&b.fact_id))); let facts = rows.iter().map(|f| f.fact_id.clone()).collect::<Vec<_>>(); let types = rows.iter().map(|f| f.context_type.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>(); let semantics = rows.iter().map(|f| f.semantic_digest.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>(); let evidence = rows.iter().map(|f| f.evidence_digest.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>(); let provenance = rows.iter().map(|f| f.provenance_digest.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>(); let mut selected=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut selected_types=BTreeSet::new();let mut omission=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new(); for f in &rows { if f.scope != q.scope || !f.policy_allowed || !f.local_only { blocked.insert(f.fact_id.clone()); omission.insert(format!("{}:scope-policy-locality",f.fact_id)); } else if f.replay_identity != q.replay_identity || !f.protected_closure || !matches!(f.evidence_state,ContextEvidenceState::Supported) { unresolved.insert(f.fact_id.clone()); uncertainty.insert(format!("{}:evidence-or-closure",f.fact_id)); } else { selected.insert(f.fact_id.clone()); selected_types.insert(f.context_type.clone()); } omission.extend(f.omission_order.iter().map(|e| format!("{}:{e}",f.fact_id))); if f.negative_result { negative.insert(format!("{}:negative-result",f.fact_id)); } } let missing_f=q.required_fact_order.iter().filter(|id|!facts.contains(id)).cloned().collect::<BTreeSet<_>>(); let missing_t=q.required_context_type_order.iter().filter(|id|!types.contains(id)).cloned().collect::<BTreeSet<_>>(); omission.extend(missing_f.iter().map(|id|format!("fact:{id}:missing"))); omission.extend(missing_t.iter().map(|id|format!("context-type:{id}:missing"))); uncertainty.extend(q.adversarial_events.iter().map(|e|format!("adversarial:{e}"))); let global=!q.policy_allow||!q.protected_closure||!q.signed_approval||!q.agent_authorized||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty(); if global { blocked.extend(facts.iter().cloned()); selected.clear(); unresolved.clear(); omission.insert("request:context-release-gate-blocked".into()); } let disposition=if global||!blocked.is_empty(){ContextContractDisposition::Blocked}else if selected.is_empty()||!missing_f.is_empty()||!missing_t.is_empty(){ContextContractDisposition::Unresolved}else{ContextContractDisposition::Qualified}; if disposition!=ContextContractDisposition::Qualified{omission.insert("request:context-not-release-ready".into());} let effects=if disposition==ContextContractDisposition::Qualified{vec![format!("view:compiled-context:{}",q.request_id)]}else{vec!["block:unsafe-release".into()]}; let payload=json!({"schema_version":"aurora-research-contract-v1","contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":q.request_id,"workflow_id":q.workflow_id,"scope":q.scope,"disposition":disposition,"fact_order":facts,"selected_fact_order":selected,"unresolved_fact_order":unresolved,"blocked_fact_order":blocked,"missing_fact_order":missing_f,"context_type_order":types,"selected_context_type_order":selected_types,"missing_context_type_order":missing_t,"semantic_order":semantics,"evidence_order":evidence,"provenance_order":provenance,"omission_order":omission,"uncertainty_order":uncertainty,"negative_evidence_order":negative,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY}); let context_digest=ContentHash::of_value(&payload).map_err(|e|ContextContractError::Artifact(e.to_string()))?; let artifact=ContractArtifact{schema_version:"aurora-research-contract-v1".into(),artifact_id:format!("devx-context:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:context_digest.clone(),boundary:BOUNDARY.into()}; let strings=|k:&str|payload[k].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect::<Vec<String>>(); let r=CompiledResearchContext6{schema_version:"aurora-research-contract-v1".into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:q.request_id.clone(),workflow_id:q.workflow_id.clone(),scope:q.scope.clone(),disposition,fact_order:strings("fact_order"),selected_fact_order:strings("selected_fact_order"),unresolved_fact_order:strings("unresolved_fact_order"),blocked_fact_order:strings("blocked_fact_order"),missing_fact_order:strings("missing_fact_order"),context_type_order:strings("context_type_order"),selected_context_type_order:strings("selected_context_type_order"),missing_context_type_order:strings("missing_context_type_order"),semantic_order:semantics,evidence_order:evidence,provenance_order:provenance,omission_order:strings("omission_order"),uncertainty_order:strings("uncertainty_order"),negative_evidence_order:strings("negative_evidence_order"),replay_identity:q.replay_identity.clone(),context_digest,artifact,effect_receipts:strings("effect_receipts"),raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into()}; r.validate()?; Ok(r)
}
fn validate_request(q:&ContextCompilationContractRequest3)->Result<(),ContextContractError>{if q.schema_version!=INPUT_SCHEMA||q.request_id.trim().is_empty()||q.workflow_id.trim().is_empty()||q.scope.trim().is_empty()||q.required_fact_order.is_empty()||q.required_context_type_order.is_empty()||q.facts.is_empty()||!canonical(&q.required_fact_order)||!canonical(&q.required_context_type_order)||!canonical(&q.adversarial_events)||!digest(&q.replay_identity)||!q.raw_data_local||!q.aggregate_only||q.boundary!=BOUNDARY{return Err(invalid("context request identity, closure, replay, locality, or boundary is invalid"));}let mut ids=BTreeSet::new();for f in &q.facts{if f.fact_id.trim().is_empty()||f.study_id.trim().is_empty()||f.context_type.trim().is_empty()||f.scope.trim().is_empty()||!ids.insert(f.fact_id.clone())||!digest(&f.semantic_digest)||!digest(&f.evidence_digest)||!digest(&f.provenance_digest)||!digest(&f.replay_identity)||!canonical(&f.omission_order){return Err(invalid("context fact identity, digests, or ordering is invalid"));}}Ok(())}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn q()->ContextCompilationContractRequest3{let f=|id:&str|ContextFact4{fact_id:id.into(),study_id:"study:1".into(),context_type:format!("type:{id}"),scope:"scope:1".into(),semantic_digest:h(id),evidence_digest:h("e"),provenance_digest:h("p"),replay_identity:h("r"),evidence_state:ContextEvidenceState::Supported,policy_allowed:true,protected_closure:true,local_only:true,omission_order:vec![],negative_result:false};ContextCompilationContractRequest3{schema_version:INPUT_SCHEMA.into(),request_id:"ctx:1".into(),workflow_id:"wf:1".into(),scope:"scope:1".into(),required_fact_order:vec!["f:1".into(),"f:2".into()],required_context_type_order:vec!["type:f:1".into(),"type:f:2".into()],facts:vec![f("f:1"),f("f:2")],replay_identity:h("r"),policy_allow:true,protected_closure:true,signed_approval:true,agent_authorized:true,raw_data_local:true,aggregate_only:true,adversarial_events:vec![],boundary:BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(compile_context_contract(&q()).unwrap().disposition,ContextContractDisposition::Qualified)}#[test]fn policy_blocks(){let mut x=q();x.policy_allow=false;assert_eq!(compile_context_contract(&x).unwrap().disposition,ContextContractDisposition::Blocked)}#[test]fn negative_is_retained(){let mut x=q();x.facts[0].negative_result=true;assert!(!compile_context_contract(&x).unwrap().negative_evidence_order.is_empty())}}
